def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    for opp_id in opponents_status:
        opp = opponents_status[opp_id]
        if opp.get('alive'):
            alive_opponents.append(opp)

    players_alive = 1 + len(alive_opponents)

    visible_prev_bids = []
    desperate_opponents = 0
    rich_aggressive = 0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            visible_prev_bids.append(bid)
            if bid >= DAILY_SALARY * 0.8:
                rich_aggressive += 1
        if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 10) <= 3:
            desperate_opponents += 1

    expected_units = float(supply) / float(WATER_REQ)
    scarcity = expected_units < players_alive

    if hp <= 2 or no_water_days >= 2:
        base = DAILY_SALARY * 0.96
    elif hp <= 4 or no_water_days >= 1:
        base = DAILY_SALARY * 0.78
    else:
        if scarcity:
            base = DAILY_SALARY * 0.58
        else:
            base = DAILY_SALARY * 0.42

    if visible_prev_bids:
        max_prev = max(visible_prev_bids)
        if hp <= 4 or no_water_days >= 1:
            base = max(base, min(DAILY_SALARY * 0.97, max_prev + 2.0))
        else:
            if max_prev >= DAILY_SALARY * 0.9 and hp >= 6:
                base = min(base, DAILY_SALARY * 0.35)
            elif scarcity:
                base = max(base, min(DAILY_SALARY * 0.82, max_prev + 1.0))

    if desperate_opponents >= max(1, len(alive_opponents) // 2):
        base += 4.0
    if rich_aggressive >= 2 and hp >= 6 and no_water_days == 0:
        base -= 6.0

    if float(supply) >= 23.0 and hp >= 5 and no_water_days == 0:
        base -= 5.0
    elif float(supply) <= 16.0:
        base += 5.0

    base = max(0.0, min(float(budget), base))

    if budget < DAILY_SALARY * 0.35:
        if hp <= 3 or no_water_days >= 1:
            return float(budget)
        return max(0.0, float(budget) * 0.55)

    return float(base)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    SUPPLY = int(day_context['supply'])
    DAY = int(day_context['day'])
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    my_hp = int(my_status['hp'])
    my_budget = int(my_status['budget'])

    # Default baseline bid based on supply
    baseline = min(my_budget, DAILY_SALARY * 0.5)

    if not alive_opponents:
        # Only me, bid minimal
        return min(my_budget, DAILY_SALARY * 0.3)

    # Analyze yesterday's opponent behavior from previous_trace
    high_bid_yesterday = 0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and 'bid' in prev and prev['bid'] is not None:
            high_bid_yesterday = max(high_bid_yesterday, float(prev['bid']))

    # Adjust based on my health
    if my_hp <= 2:
        # Desperate: need water
        aggressive_bid = min(my_budget, DAILY_SALARY * 0.9)
        return aggressive_bid
    elif my_hp <= 4:
        # Moderate need, counter opponents
        if high_bid_yesterday > DAILY_SALARY * 0.7:
            # Opponents were aggressive yesterday, maybe conserve
            return min(my_budget, DAILY_SALARY * 0.55)
        else:
            return min(my_budget, DAILY_SALARY * 0.6)
    else:
        # Healthy
        if high_bid_yesterday > DAILY_SALARY * 0.8:
            # Opponent desperate, undercut them
            return min(my_budget, DAILY_SALARY * 0.45)
        else:
            return min(my_budget, baseline)
